     1	import React from 'react';
     2	import { Global, css } from '@emotion/react';
     3	import { bundleBasePath, getEnvBasePath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';
     4	
     5	/**
     6	 * @font-face declarations for the self-hosted Futura Round faces.
     7	 *
     8	 * This is the only thing the font needs. `foundation/fonts.ts` already lists 'Futura Round'
     9	 * as first preference in both FONT_REGULAR and FONT_MEDIUM, and every layer below it —
    10	 * zimmTokens' --zimm-font-family-*, the 22 textStyles, every component recipe — already
    11	 * resolves through that stack. Declaring the faces makes the name resolvable; nothing else in
    12	 * the styling chain changes.
    13	 *
    14	 * Only two faces exist because only two are used: all 22 textStyles resolve to fontWeight 400
    15	 * or 500, and fonts.body === fonts.heading, so there is no third stack to serve.
    16	 *
    17	 * Injected with a raw Emotion <Global> rather than Chakra's styles.global, for the same reason
    18	 * zimmTokensGlobal.tsx documents: Chakra's style processor mangles quoted font-family values,
    19	 * collapsing a stack like "'Futura Round', 'Century Gothic', sans-serif" to a single family.
    20	 * Rendered in the app by _app-config/index.tsx AND in Storybook by .storybook/preview.tsx, so
    21	 * type resolves identically in isolation and in the app — one shared definition so the two
    22	 * mount points cannot drift.
    23	 */
    24	
    25	/**
    26	 * Bundle-prefixed asset root, resolved synchronously.
    27	 *
    28	 * This deliberately reimplements the two lines of `getAssetUrl` rather than importing it.
    29	 * That helper lives in `@salesforce/pwa-kit-react-sdk/ssr/universal/utils`, which also pulls
    30	 * in `ssr-config` (cosmiconfig → fs) — fine on the server, but it would land in the browser
    31	 * and Storybook bundles. Importing it lazily to dodge that is worse: this module's css`` is
    32	 * evaluated at module-init, so an async import can never populate in time and every URL
    33	 * silently loses its bundle prefix, 404s, and the browser falls back to the system font.
    34	 *
    35	 * `ssr-namespace-paths` is dependency-free, so it imports statically and resolves in one tick.
    36	 *
    37	 *   SSR      → `${getEnvBasePath()}${bundleBasePath}/${BUNDLE_ID}/`  e.g. /mobify/bundle/development/
    38	 *   Browser  → window.Progressive.buildOrigin, set by the PWA Kit client runtime pre-hydration
    39	 *   Storybook→ neither applies, so the bare /static path is used; .storybook/main.js maps
    40	 *              overrides/app/static to /static via staticDirs, so it resolves there too.
    41	 */
    42	const assetRoot = (): string => {
    43	  if (typeof window !== 'undefined') {
    44	    // No type declarations ship for this SDK-injected global, so a narrow assertion is the
    45	    // only option. Storybook has no Progressive global and falls through to '/'.
    46	    const buildOrigin = (window as unknown as { Progressive?: { buildOrigin?: string } }).Progressive?.buildOrigin;
    47	    return buildOrigin ?? '/';
    48	  }
    49	  return `${getEnvBasePath()}${bundleBasePath}/${process.env.BUNDLE_ID || 'development'}/`;
    50	};
    51	
    52	const fontUrl = (filename: string): string => `${assetRoot()}static/fonts/${filename}`;
    53	
    54	const fontFaceCss = css`
    55	  @font-face {
    56	    font-family: 'Futura Round';
    57	    src: url('${fontUrl('FuturaRound-Regular.woff2')}') format('woff2');
    58	    font-weight: 400;
    59	    font-style: normal;
    60	    font-display: swap;
    61	  }
    62	  @font-face {
    63	    font-family: 'Futura Round';
    64	    src: url('${fontUrl('FuturaRound-Medium.woff2')}') format('woff2');
    65	    font-weight: 500;
    66	    font-style: normal;
    67	    font-display: swap;
    68	  }
    69	`;
    70	
    71	/** Declares the self-hosted Futura Round faces. Render once, high in the tree. */
    72	export function ZimmFontFace(): React.ReactElement {
    73	  return <Global styles={fontFaceCss} />;
    74	}

