import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { pickMostSpecificByRegion } from './resolveByRegion';
type F = { sys: { id: string; updatedAt?: string }; fields: { regions?: ReadonlyArray<{ fields: { siteId: string } }> } };
const e = (id: string, s?: string[], u?: string): F => ({ sys: { id, updatedAt: u }, fields: { regions: s ? s.map((x) => ({ fields: { siteId: x } })) : undefined } });
describe('empirical tie probes', () => {
  beforeEach(() => { vi.spyOn(console, 'warn').mockImplementation(() => {}); });
  afterEach(() => { vi.restoreAllMocks(); });

  test('EQUAL updatedAt: outcome IS order-dependent', () => {
    const SAME = '2026-06-01T00:00:00.000Z';
    const a = e('a', ['ZimmermannUS'], SAME); const b = e('b', ['ZimmermannUS'], SAME);
    const fwd = pickMostSpecificByRegion([a, b], 'ZimmermannUS')!.sys.id;
    const rev = pickMostSpecificByRegion([b, a], 'ZimmermannUS')!.sys.id;
    console.log('EQUAL ts -> fwd:', fwd, 'rev:', rev, '| warns:', (console.warn as any).mock.calls.length);
    expect(fwd).toBe('a'); expect(rev).toBe('b'); // order-dependent
    expect(console.warn).toHaveBeenCalledTimes(0); // NO warning at all
  });

  test('ABSENT updatedAt: outcome IS order-dependent, no warning', () => {
    const a = e('a', ['ZimmermannUS']); const b = e('b', ['ZimmermannUS']);
    const fwd = pickMostSpecificByRegion([a, b], 'ZimmermannUS')!.sys.id;
    const rev = pickMostSpecificByRegion([b, a], 'ZimmermannUS')!.sys.id;
    console.log('ABSENT ts -> fwd:', fwd, 'rev:', rev, '| warns:', (console.warn as any).mock.calls.length);
    expect(fwd).toBe('a'); expect(rev).toBe('b');
    expect(console.warn).toHaveBeenCalledTimes(0);
  });

  test('[newer, older] selects newer but emits NO warning (asymmetric)', () => {
    const older = e('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
    const newer = e('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
    expect(pickMostSpecificByRegion([newer, older], 'ZimmermannUS')!.sys.id).toBe('newer');
    console.log('[newer,older] warns:', (console.warn as any).mock.calls.length);
    expect(console.warn).toHaveBeenCalledTimes(0);
  });

  test('MIXED: one has ts, other absent -> present wins regardless of order', () => {
    const withTs = e('withTs', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
    const noTs = e('noTs', ['ZimmermannUS']);
    expect(pickMostSpecificByRegion([noTs, withTs], 'ZimmermannUS')!.sys.id).toBe('withTs');
    expect(pickMostSpecificByRegion([withTs, noTs], 'ZimmermannUS')!.sys.id).toBe('withTs');
  });
});
